//New approach
const updateDepartmentalPrescription = (department_id, dependant, item,owner) => {

  console.log("item", item);
  console.log("owner", owner);
  let thisPrescription = null;
  let modifiedPrescriptions = [];
  let modifiedPrescriptionItems = [];
  let allDepartmentalPrescriptions = [];
  let departmentalPrescriptions = [];
  if (localStorage.getItem("departmentalPrescriptions")) {
    allDepartmentalPrescriptions = JSON.parse(
      localStorage.getItem("departmentalPrescriptions")
    );

    departmentalPrescriptions=allDepartmentalPrescriptions?.filter(x=>x.owner=owner)

    if (departmentalPrescriptions.length > 0) {
      //Isolate current order
      let thisPrescription = departmentalPrescriptions.find(
        (x) =>
          x.dependant_id === dependant.id && x.department_id === department_id
      );
      if (thisPrescription) {
        console.log("Prescription exists");
        //Remove order from orders list
        const prescriptionsMinusThisPrescription =
          departmentalPrescriptions.filter(
            (x) =>
              x.dependant_id !== dependant.id &&
              x.department_id !== department_id
          );

        let thisPrescriptionItem = thisPrescription.items.find(
          (x) => x.preparation_id === item["preparation_id"]
        );
        if (thisPrescriptionItem) {
          console.log("This item exists in prescription");
          const prescriptionItemsMinusThisItem = thisPrescription.items.filter(
            (x) => x.preparation_id !== item["preparation_id"]
          );
          thisPrescriptionItem["frequency_id"] = item["frequency_id"];
          thisPrescriptionItem["dosage"] = item["dosage"];
          thisPrescriptionItem["frequency_title"] = item["frequency_title"];
          thisPrescriptionItem["duration"] = item["duration"];
          thisPrescriptionItem["special_instruction"] =
            item["special_instruction"];

          thisPrescription.items = [
            ...prescriptionItemsMinusThisItem,
            thisPrescriptionItem,
          ];
        } else {
          console.log("Add new item");
          thisPrescription.items = [...thisPrescription.items, item];
        }

        modifiedPrescriptions = [
          ...prescriptionsMinusThisPrescription,
          thisPrescription,
        ];

        localStorage.removeItem("departmentalPrescriptions");
        localStorage.setItem(
          "departmentalPrescriptions",
          JSON.stringify(modifiedPrescriptions)
        );
      } else {
        console.log("Prescription does not exists");
        const newPrescription = {
            dependant_name: dependant.title,
            dependant_id: dependant.id,
            department_id: department_id,
            owner: owner,
            items: [
              {
                preparation_id: item["preparation_id"],
                preparation_title: item["preparation_title"],
                duration: item["duration"],
                special_instruction: item["special_instruction"],
                frequency_id: item["frequency_id"],
                frequency_title: item["frequency_title"],
                dosage: item["dosage"],
              },
            ],
          };
    
          console.log("Created new and first", newPrescription);
    
          modifiedPrescriptions = [...departmentalPrescriptions, newPrescription];
    
          localStorage.setItem(
            "departmentalPrescriptions",
            JSON.stringify(modifiedPrescriptions)
          );
      }
    } else {
        console.log("create new presciption and add to existing")
      const newPrescription = {
        dependant_name: dependant.title,
        dependant_id: dependant.id,
        department_id: department_id,
        owner: owner,
        items: [
          {
            preparation_id: item["preparation_id"],
            preparation_title: item["preparation_title"],
            duration: item["duration"],
            special_instruction: item["special_instruction"],
            frequency_id: item["frequency_id"],
            frequency_title: item["frequency_title"],
            dosage: item["dosage"],
          },
        ],
      };

      console.log("Created new and first", newPrescription);

      modifiedPrescriptions = [newPrescription];

      localStorage.setItem(
        "departmentalPrescriptions",
        JSON.stringify(modifiedPrescriptions)
      );
    }
  } else {
    const newPrescription = {
      dependant_name: dependant.title,
      dependant_id: dependant.id,
      department_id: department_id,
      owner: owner,
      items: [
        {
          preparation_id: item["preparation_id"],
          preparation_title: item["preparation_title"],
          duration: item["duration"],
          special_instruction: item["special_instruction"],
          frequency_id: item["frequency_id"],
          frequency_title: item["frequency_title"],
          dosage: item["dosage"],
        },
      ],
    };

    console.log("Created new and first", newPrescription);

    modifiedPrescriptions = [newPrescription];

    localStorage.setItem(
      "departmentalPrescriptions",
      JSON.stringify(modifiedPrescriptions)
    );
  }

  return modifiedPrescriptions;
};

export { updateDepartmentalPrescription };
